                <h1 id="introduction">Introduction</h1>
<p>API pública do SIMAH para acesso a dados hidrológicos e ambientais do estado da Bahia.</p>
<aside>
    <strong>Base URL</strong>: <code>https://simah.studio1.tech</code>
</aside>

                <h1 id="authenticating-requests">Authenticating requests</h1>
<p>To authenticate requests, include a <strong><code>X-Api-Key</code></strong> header with the value <strong><code>"{SUA_CHAVE_DE_API}"</code></strong>.</p>
<p>All authenticated endpoints are marked with a <code>requires authentication</code> badge in the documentation below.</p>
<p>Solicite sua chave de API em <a href="/api-key">Solicitar Acesso à API</a>.</p>
            </div>
