                                        <div class="sl-flex sl-overflow-x-hidden sl-text-lg sl-select-all">
                        <div dir="rtl"
                             class="sl-overflow-x-hidden sl-truncate sl-text-muted">https://simah.studio1.tech</div>
                        <div class="sl-flex-1 sl-font-semibold">/api/v1/hidroweb/{station_code}/forecast</div>
                    </div>

                                                    <div class="sl-font-prose sl-font-semibold sl-px-1.5 sl-py-0.5 sl-text-on-primary sl-rounded-lg"
                                 style="background-color: darkred"
                            >requires authentication
                            </div>
                                                                                    </div>
        </div>

        <p>Retorna as previsões de vazão de uma estação ANA/HidroWeb pelo código.
O parâmetro <code>year</code> é obrigatório. O parâmetro <code>month</code> é opcional — se omitido, retorna todos os meses do ano.</p>
